import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-08-03","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-08-03","date":"2021-08-03T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph","Orchestrator","Container Images","LSO Project","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-03.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-03.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-08-03.md"};function l(n,a,s,h,c,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-orchestrator-周会" tabindex="-1">会议主题：Orchestrator 周会 <a class="header-anchor" href="#会议主题-orchestrator-周会" aria-label="Permalink to &quot;会议主题：Orchestrator 周会&quot;">​</a></h4><h4 id="日期-2021年8月3日" tabindex="-1">日期：2021年8月3日 <a class="header-anchor" href="#日期-2021年8月3日" aria-label="Permalink to &quot;日期：2021年8月3日&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>容器镜像问题</strong></p><ul><li><strong>问题描述</strong>：在尝试将 Pacific Beats 升级到 16.5 版本时，CephFS 无法启动，原因可能是新容器构建基于 daemon 基础镜像而非 daemon 镜像，导致 Dockerfile 缺少入口点，start nfs bash 脚本未被调用。</li><li><strong>讨论内容</strong>：讨论了新容器格式缺少入口点，不适用于 CephFS，建议继续使用传统的 daemon 镜像，以及旧容器镜像的维护问题。</li><li><strong>决定事项</strong>：继续使用 6.0.4 版本的容器镜像作为稳定版本，并确认 6.0.x 系列将继续维护。</li><li><strong>后续行动计划</strong>：确认旧容器镜像的维护计划，确保新版本的稳定性和兼容性，监控新容器格式的测试和部署情况。</li></ul></li><li><p><strong>LSO 项目更新</strong></p><ul><li><strong>项目概述</strong>：讨论了 LSO 项目的需求文档，计划与 LSO 团队合作，明确项目需求和目标。</li><li><strong>讨论内容</strong>：创建了 Google Doc 用于团队间的协作和讨论，确认项目需要支持 vanilla Kubernetes，成为一个上游项目。</li><li><strong>决定事项</strong>：继续完善需求文档，计划与 LSO 团队进行详细讨论。</li><li><strong>后续行动计划</strong>：确保文档准备就绪，与 LSO 团队进行深入讨论，跟进与 Duncan 的会议，讨论产品管理相关事宜。</li></ul></li></ol><h4 id="其他议题" tabindex="-1">其他议题： <a class="header-anchor" href="#其他议题" aria-label="Permalink to &quot;其他议题：&quot;">​</a></h4><ul><li><strong>Crimson 和 Encephalidium 容器镜像</strong>：讨论了 Crimson 的容器镜像问题，确认其为不同的构建，带有特定的构建标志。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>会议主要解决了容器镜像的兼容性问题，并讨论了 LSO 项目的进展。团队将继续监控和维护相关容器镜像，确保项目的稳定推进。同时，LSO 项目的需求文档将继续完善，以便与团队进行更深入的讨论和合作。</p><h4 id="下一步行动" tabindex="-1">下一步行动： <a class="header-anchor" href="#下一步行动" aria-label="Permalink to &quot;下一步行动：&quot;">​</a></h4><ul><li>确认并维护旧容器镜像的稳定性和兼容性。</li><li>完善 LSO 项目需求文档，准备与 LSO 团队进行详细讨论。</li><li>跟进与 Duncan 的会议，讨论产品管理相关事宜。</li></ul>',12)])])}const g=e(i,[["render",l]]);export{p as __pageData,g as default};
